#include <Arduino.h>
const int SHCP_PIN = A2;  
const int STCP_PIN = A1;  
const int DS_PIN = A0;    
const byte segmentCodes[10] = {
  0b11000000, 
  0b11111001, 
  0b10100100, 
  0b10110000, 
  0b10011001, 
  0b10010010, 
  0b10000010, 
  0b11111000, 
  0b10000000, 
  0b10010000  
};
int currentValue = 0;
unsigned long lastUpdate = 0;
const int interval = 2000;

void setup();
void loop();
void updateDisplays(int value);
void setup() {
  for (int pin = 2; pin <= 11; pin++) {
    pinMode(pin, OUTPUT);
  }
  pinMode(DS_PIN, OUTPUT);
  pinMode(SHCP_PIN, OUTPUT);
  pinMode(STCP_PIN, OUTPUT);
  updateDisplays(0); 
}
void loop() {
  if (millis() - lastUpdate >= interval) {
    currentValue = (currentValue + 1) % 10;
    updateDisplays(currentValue);
    lastUpdate = millis();
  }
}
void updateDisplays(int value) {
  digitalWrite(STCP_PIN, LOW);
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, segmentCodes[value]);
  digitalWrite(STCP_PIN, HIGH);
  digitalWrite(STCP_PIN, LOW);
  for (int led = 2; led <= 11; led++) {
    digitalWrite(led, (led - 2 < value) ? HIGH : LOW);
  }
}
